(function(){
  var c=document.getElementById("container"),tpl=document.getElementById("social");
  document.querySelectorAll("[data-social]").forEach(function(n){n.appendChild(tpl.content.cloneNode(true))});
  function mode(up){c.classList.toggle("sign-up-mode",up);document.title=up?"UCaaS · Sign up":"UCaaS · Sign in";try{history.replaceState(history.state,"",up?"#signup":"#signin")}catch(e){}}
  document.getElementById("to-up").addEventListener("click",function(){mode(true)});
  document.getElementById("to-in").addEventListener("click",function(){mode(false)});
  function fromHash(){mode(/signup/i.test(location.hash))}
  window.addEventListener("hashchange",fromHash);
  /* first paint: jump straight to the right side, no sweeping animation */
  c.classList.add("no-anim");fromHash();requestAnimationFrame(function(){requestAnimationFrame(function(){c.classList.remove("no-anim")})});
  document.querySelectorAll("form").forEach(function(f){f.addEventListener("submit",function(e){e.preventDefault()})});
  document.querySelectorAll(".social-icon").forEach(function(a){a.addEventListener("click",function(e){e.preventDefault()})});
})();
